16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "registration_date")
63	    private LocalDate registrationDate;
64	
65	    @Column(name = "birth_date")
66	    private LocalDate birthDate;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "possible_duplicate")
75	    private Boolean possibleDuplicate;
76	
77	    @Column(name = "possible_duplicate_of")
78	    private Integer possibleDuplicateOf;
79	
80	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
81	    private Set<Pet> pets;
82	
83	    public String getAddress() {
84	        return this.address;
85	    }
86	
87	    public void setAddress(String address) {
88	        this.address = address;
89	    }
90	
91	    public String getCity() {
92	        return this.city;
93	    }
94	
95	    public void setCity(String city) {
96	        this.city = city;
97	    }
98	
99	    public String getTelephone() {
100	        return this.telephone;
101	    }
102	
103	    public void setTelephone(String telephone) {
104	        this.telephone = telephone;
105	    }
106	
107	    public String getEmail() {
108	        return this.email;
109	    }
110	
111	    public void setEmail(String email) {
112	        this.email = email;
113	    }
114	
115	    /**
116	     * Whether this owner has a non-blank email address on file.
117	     */
118	    public boolean hasEmail() {
119	        return this.email != null && !this.email.isBlank();
120	    }
121	
122	    public String getPostcode() {
123	        return this.postcode;
124	    }
125	
126	    public void setPostcode(String postcode) {
127	        this.postcode = postcode;
128	    }
129	
130	    public String getCustomerCode() {
131	        return this.customerCode;
132	    }
133	
134	    public void setCustomerCode(String customerCode) {
135	        this.customerCode = customerCode;
136	    }
137	
138	    public LocalDate getRegistrationDate() {
139	        return this.registrationDate;
140	    }
141	
142	    public void setRegistrationDate(LocalDate registrationDate) {
143	        this.registrationDate = registrationDate;
144	    }
145	
146	    public LocalDate getBirthDate() {
147	        return this.birthDate;
148	    }
149	
150	    public void setBirthDate(LocalDate birthDate) {
151	        this.birthDate = birthDate;
152	    }
153	
154	    public String getHouseholdId() {
155	        return this.householdId;
156	    }
157	
158	    public void setHouseholdId(String householdId) {
159	        this.householdId = householdId;
160	    }
161	
162	    public Integer getNamesakeCount() {
163	        return this.namesakeCount;
164	    }
165	
166	    public void setNamesakeCount(Integer namesakeCount) {
167	        this.namesakeCount = namesakeCount;
168	    }
169	
170	    public Boolean getPossibleDuplicate() {
171	        return this.possibleDuplicate;
172	    }
173	
174	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
175	        this.possibleDuplicate = possibleDuplicate;
176	    }
177	
178	    public Integer getPossibleDuplicateOf() {
179	        return this.possibleDuplicateOf;
180	    }
181	
182	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
183	        this.possibleDuplicateOf = possibleDuplicateOf;
184	    }
185	
186	    protected Set<Pet> getPetsInternal() {
187	        if (this.pets == null) {
188	            this.pets = new HashSet<>();
189	        }
190	        return this.pets;
191	    }
192	
193	    protected void setPetsInternal(Set<Pet> pets) {
194	        this.pets = pets;
195	    }
196	
197	    public List<Pet> getPets() {
198	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
199	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
200	        return Collections.unmodifiableList(sortedPets);
201	    }
202	
203	    public void setPets(List<Pet> pets) {
204	        this.pets = new HashSet<>(pets);
205	    }
206	
207	    public void addPet(Pet pet) {
208	        getPetsInternal().add(pet);
209	        pet.setOwner(this);
210	    }
211	
212	    /**
213	     * Return the Pet with the given name, or null if none found for this Owner.
214	     *
215	     * @param name to test
216	     * @return true if pet name is already in use
217	     */
218	    public Pet getPet(String name) {
219	        return getPet(name, false);
220	    }
221	
222	    /**
223	     * Return the Pet with the given name, or null if none found for this Owner.
224	     *
225	     * @param name to test
226	     * @return true if pet name is already in use
227	     */
228	    public Pet getPet(String name, boolean ignoreNew) {
229	        name = name.toLowerCase();
230	        for (Pet pet : getPetsInternal()) {
231	            if (!ignoreNew || !pet.isNew()) {
232	                String compName = pet.getName();
233	                compName = compName.toLowerCase();
234	                if (compName.equals(name)) {
235	                    return pet;
236	                }
237	            }
238	        }
239	        return null;
240	    }
241	
242	    public Pet getPet(Integer petId) {
243	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
244	    }
245	
246	    @Override
247	    public String toString() {
248	        return new ToStringCreator(this)
249	
250	            .append("id", this.getId())
251	            .append("new", this.isNew())
252	            .append("lastName", this.getLastName())
253	            .append("firstName", this.getFirstName())
254	            .append("address", this.address)
255	            .append("city", this.city)
256	            .append("telephone", this.telephone)
257	            .toString();
258	    }
259	}
