17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.controller.CityCapacityExceededException;
33	import org.springframework.samples.petclinic.rest.controller.DailyRegistrationLimitExceededException;
34	import org.springframework.samples.petclinic.rest.controller.HouseholdDuplicateException;
35	import org.springframework.samples.petclinic.rest.controller.FutureRegistrationDateException;
36	import org.springframework.samples.petclinic.rest.controller.InvalidTelephoneException;
37	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
38	import org.springframework.security.access.AccessDeniedException;
39	import org.springframework.validation.BindingResult;
40	import org.springframework.validation.FieldError;
41	import org.springframework.web.bind.MethodArgumentNotValidException;
42	import org.springframework.web.bind.annotation.ControllerAdvice;
43	import org.springframework.web.bind.annotation.ExceptionHandler;
44	import org.springframework.web.bind.annotation.ResponseBody;
45	
46	/**
47	 * Global Exception handler for REST controllers.
48	 * <p>
49	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
50	 *
51	 * @author Vitaliy Fedoriv
52	 * @author Alexander Dudkin
53	 */
54	@ControllerAdvice
55	public class ExceptionControllerAdvice {
56	
57	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
58	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
59	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
60	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
61	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner already exists in this household";
62	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
63	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners for today has already been reached";
64	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the server date";
65	
66	    /**
67	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
68	     * class.
69	     *
70	     * @param e     Object referring to the thrown exception.
71	     * @param status HTTP response status.
72	     * @param url URL request.
73	     */
74	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
75	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
76	        problemDetail.setType(URI.create(url.toString()));
77	        problemDetail.setTitle(e.getClass().getSimpleName());
78	        problemDetail.setDetail(detail);
79	        problemDetail.setProperty("timestamp", Instant.now());
80	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
81	        return problemDetail;
82	    }
83	
84	    /**
85	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
86	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
87	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
88	     * would catch it and report an authorization failure as a 500.
89	     *
90	     * @param e The {@link AccessDeniedException} to propagate
91	     * @throws AccessDeniedException always
92	     */
93	    @ExceptionHandler(AccessDeniedException.class)
94	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
95	        throw e;
96	    }
97	
98	    /**
99	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
100	     *
101	     * @param e The {@link Exception} to be handled
102	     * @param request {@link HttpServletRequest} object referring to the current request.
103	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
104	     */
105	    @ExceptionHandler(Exception.class)
106	    @ResponseBody
107	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
108	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
109	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
110	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
111	        return ResponseEntity.status(status).body(detail);
112	    }
113	
114	    /**
115	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
116	     * method returns a 404 Not Found status if an entity does not exist.
117	     *
118	     * @param e The {@link DataIntegrityViolationException} to be handled
119	     * @param request {@link HttpServletRequest} object referring to the current request.
120	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
121	     */
122	    @ExceptionHandler(DataIntegrityViolationException.class)
123	    @ResponseBody
124	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
125	        logger.warn("Data integrity violation at {} {}: {}",
126	            request.getMethod(),
127	            request.getRequestURI(),
128	            e.getMessage());
129	        logger.debug("Data integrity violation stacktrace", e);
130	        HttpStatus status = HttpStatus.NOT_FOUND;
131	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
132	        return ResponseEntity.status(status).body(detail);
133	    }
134	
135	    /**
136	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone does not
137	     * reduce to exactly ten digits after non-digit characters are stripped.
138	     *
139	     * @param e The {@link InvalidTelephoneException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
142	     */
143	    @ExceptionHandler(InvalidTelephoneException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
146	        HttpStatus status = HttpStatus.BAD_REQUEST;
147	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
148	        return ResponseEntity.status(status).body(detail);
149	    }
150	
151	    /**
152	     * Handles {@link HouseholdDuplicateException} raised when an owner is created that would be a
153	     * second member of an existing household (same last name and postcode) without declaring
154	     * itself a shared-household member.
155	     *
156	     * @param e The {@link HouseholdDuplicateException} to be handled
157	     * @param request {@link HttpServletRequest} object referring to the current request.
158	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
159	     */
160	    @ExceptionHandler(HouseholdDuplicateException.class)
161	    @ResponseBody
162	    public ResponseEntity<ProblemDetail> handleHouseholdDuplicateException(HouseholdDuplicateException e, HttpServletRequest request) {
163	        HttpStatus status = HttpStatus.CONFLICT;
164	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
165	        return ResponseEntity.status(status).body(detail);
166	    }
167	
168	    /**
169	     * Handles {@link CityCapacityExceededException} raised when an owner is created in a city
170	     * that already contains the maximum number of owners.
171	     *
172	     * @param e The {@link CityCapacityExceededException} to be handled
173	     * @param request {@link HttpServletRequest} object referring to the current request.
174	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
175	     */
176	    @ExceptionHandler(CityCapacityExceededException.class)
177	    @ResponseBody
178	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
179	        HttpStatus status = HttpStatus.CONFLICT;
180	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
181	        return ResponseEntity.status(status).body(detail);
182	    }
183	
184	    /**
185	     * Handles {@link DailyRegistrationLimitExceededException} raised when an owner is created
186	     * after the maximum number of owners for the current day has already been registered.
187	     *
188	     * @param e The {@link DailyRegistrationLimitExceededException} to be handled
189	     * @param request {@link HttpServletRequest} object referring to the current request.
190	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
191	     */
192	    @ExceptionHandler(DailyRegistrationLimitExceededException.class)
193	    @ResponseBody
194	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitExceededException(DailyRegistrationLimitExceededException e, HttpServletRequest request) {
195	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
196	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
197	        return ResponseEntity.status(status).body(detail);
198	    }
199	
200	    /**
201	     * Handles {@link FutureRegistrationDateException} raised when an owner is created with a
202	     * supplied registration date that is later than the server's current date.
203	     *
204	     * @param e The {@link FutureRegistrationDateException} to be handled
205	     * @param request {@link HttpServletRequest} object referring to the current request.
206	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
207	     */
208	    @ExceptionHandler(FutureRegistrationDateException.class)
209	    @ResponseBody
210	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
211	        HttpStatus status = HttpStatus.BAD_REQUEST;
212	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
213	        return ResponseEntity.status(status).body(detail);
214	    }
215	
216	    /**
217	     * Handles exception thrown by Bean Validation on controller methods parameters
218	     *
219	     * @param e The {@link MethodArgumentNotValidException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
222	     */
223	    @ExceptionHandler(MethodArgumentNotValidException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.BAD_REQUEST;
227	        BindingErrorsResponse errors = new BindingErrorsResponse();
228	        BindingResult bindingResult = e.getBindingResult();
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
230	        if (bindingResult.hasErrors()) {
231	            errors.addAllErrors(bindingResult);
232	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
233	                .map(fieldError -> {
234	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
235	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
236	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
237	                        fieldError.getField(),
238	                        defaultMessage,
239	                        rejectedValue);
240	                    return new ValidationMessageDto(message)
241	                        .putAdditionalProperty("field", fieldError.getField())
242	                        .putAdditionalProperty("rejectedValue", rejectedValue)
243	                        .putAdditionalProperty("defaultMessage", defaultMessage);
244	                })
245	                .toList();
246	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
247	                .map(FieldError::getField)
248	                .distinct()
249	                .toList();
250	            logger.debug("Validation error at {} {}: {}",
251	                request.getMethod(),
252	                request.getRequestURI(),
253	                bindingResult.getFieldErrors());
254	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
255	            detail.setProperty("errors", invalidFields);
256	            return ResponseEntity.status(status).body(detail);
257	        }
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	}
